BEGIN; CREATE TEMP TABLE measured ("id" uuid DEFAULT uuidv7() NOT NULL,"tenant_id" uuid NOT NULL,"user_id" uuid NOT NULL,"dropped_slot_4" integer,"dropped_slot_5" integer,"confirmed_at" timestamp with time zone,"last_used_step" bigint,"dropped_slot_8" integer,"dropped_slot_9" integer,"secret_ciphertext" bytea NOT NULL,"secret_key_id" character varying(128) NOT NULL);ALTER TABLE measured DROP COLUMN "dropped_slot_4";ALTER TABLE measured DROP COLUMN "dropped_slot_5";ALTER TABLE measured DROP COLUMN "dropped_slot_8";ALTER TABLE measured DROP COLUMN "dropped_slot_9";CREATE INDEX measured_index_0 ON measured USING btree (user_id);CREATE UNIQUE INDEX measured_index_1 ON measured USING btree (id);CREATE UNIQUE INDEX measured_index_2 ON measured USING btree (tenant_id, user_id);INSERT INTO measured(tenant_id,user_id,secret_ciphertext,secret_key_id,confirmed_at,last_used_step) SELECT '00000000-0000-0000-0000-000000000001',md5('user-'||i)::uuid,decode(repeat('01',64),'hex'),'fixture-key','2026-10-01T00:00:00Z',123 FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured'),'dropped_slots',(SELECT count(*) FROM pg_attribute WHERE attrelid='measured'::regclass AND attnum>0 AND attisdropped)) FROM measured d; ROLLBACK;